import React, { useState } from 'react';
import { User, MapPin, Search, X, FileText, AlertOctagon, Calendar, CreditCard, ChevronRight, Fingerprint, Clock, ShieldCheck } from 'lucide-react';

const CitizensTab = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState(null);
  const [activeFilter, setActiveFilter] = useState('PROFILE');

  const citizens = [
    { id: 'CZ-8821', name: 'ARJUN MEHTA', area: 'GANDHI_NAGAR', zone: 'ZONE_A', status: 'ACTIVE', phone: '+91 98XXX XXXXX', joined: '12_JAN_2025' },
    { id: 'CZ-4412', name: 'SARA KHAN', area: 'SILICON_VALLEY', zone: 'ZONE_C', status: 'OVERDUE', phone: '+91 88XXX XXXXX', joined: '05_FEB_2024' },
    { id: 'CZ-9003', name: 'VIKRAM SINGH', area: 'OLD_TOWN', zone: 'ZONE_B', status: 'ACTIVE', phone: '+91 77XXX XXXXX', joined: '22_NOV_2024' },
  ];

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter select-none">

      {/* HEADER RIG */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-[#FFF24D] p-5 rounded-[24px] border-[3px] border-[#47510B] shadow-[6px_6px_0_0_#47510B]">
        <div className="flex items-center gap-3">
          <Fingerprint size={32} />
          <h1 className="text-2xl leading-none">REGISTRY</h1>
        </div>
        <input 
          type="text" 
          placeholder="FILTER..." 
          className="w-full md:w-64 bg-white border-[3px] border-[#47510B] rounded-xl p-2 px-4 outline-none text-sm"
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* 📋 LIST: Added pb-32 to fix the cut-off issue */}
      <div className="flex-grow overflow-y-auto pr-2 pb-32 custom-scrollbar grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {citizens.map(c => (
          <div key={c.id} onClick={() => setSelectedCitizen(c)} className="bg-white border-[3px] border-[#47510B] p-5 rounded-[30px] shadow-[4px_4px_0_0_#47510B] hover:translate-x-1 transition-all cursor-pointer flex justify-between items-center group">
            <div className="min-w-0">
              <p className="text-[10px] opacity-40">{c.id}</p>
              <h3 className="text-xl truncate">{c.name}</h3>
            </div>
            <ChevronRight size={20} className="group-hover:translate-x-1 transition-transform" />
          </div>
        ))}
      </div>

      {/* 🏗️ SLIM DOSSIER MODAL */}
      {selectedCitizen && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#0F172A]/80 backdrop-blur-sm animate-in fade-in duration-200" onClick={() => setSelectedCitizen(null)} />

          {/* SIZED CONTAINER: 80% Height, max-width 4xl */}
          <div className="relative w-full max-w-4xl h-[80vh] bg-[#F8FAFC] border-[4px] border-[#1E293B] rounded-[40px] shadow-[15px_15px_0_0_#6366F1] overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">

            {/* COMPACT HEADER */}
            <div className="bg-[#6366F1] p-6 text-white flex justify-between items-center shrink-0">
                <div className="flex gap-4 items-center">
                    <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-[#6366F1]">
                        <User size={32} strokeWidth={3} />
                    </div>
                    <div>
                        <p className="text-[10px] tracking-widest opacity-70">ENTRY_{selectedCitizen.id}</p>
                        <h2 className="text-3xl leading-none">{selectedCitizen.name}</h2>
                    </div>
                </div>
                <button onClick={() => setSelectedCitizen(null)} className="hover:rotate-90 transition-all p-2 bg-black/10 rounded-xl"><X size={24} /></button>
            </div>

            {/* SLIM NAV */}
            <div className="bg-[#1E293B] p-2 flex gap-2 overflow-x-auto no-scrollbar shrink-0">
              {['PROFILE', 'REPORTS', 'PENALTIES', 'SCHEDULES', 'SUBS'].map(id => (
                <button 
                  key={id}
                  onClick={() => setActiveFilter(id)}
                  className={`px-5 py-2.5 rounded-xl text-[10px] font-black transition-all ${activeFilter === id ? 'bg-white text-[#1E293B]' : 'text-white/40 hover:text-white'}`}
                >
                  {id}
                </button>
              ))}
            </div>

            {/* CONTENT AREA: pb-10 added for safe scrolling */}
            <div className="flex-grow p-8 overflow-y-auto pb-10 custom-scrollbar-indigo">

              {activeFilter === 'PROFILE' && (
                <div className="grid md:grid-cols-2 gap-6 animate-in slide-in-from-bottom-4">
                  <div className="space-y-6">
                    <div>
                      <label className="text-indigo-400 text-[10px] mb-1 block">ADDRESS_DATA</label>
                      <p className="text-2xl leading-tight">{selectedCitizen.area}, SECTOR-7, HYDERABAD</p>
                    </div>
                    <div className="bg-white p-5 rounded-3xl border-2 border-[#1E293B] shadow-[4px_4px_0_0_#1E293B]">
                        <label className="text-[8px] opacity-40">JOINED_NETWORK</label>
                        <p className="text-lg">{selectedCitizen.joined}</p>
                    </div>
                  </div>
                  <div className="bg-[#1E293B] rounded-3xl p-6 text-white flex flex-col items-center justify-center text-center">
                     <ShieldCheck size={48} className="text-[#FACC15] mb-3" />
                     <h3 className="text-xl">STATUS: VERIFIED</h3>
                  </div>
                </div>
              )}

              {activeFilter === 'REPORTS' && (
                <div className="space-y-3">
                  {[1, 2].map(i => (
                    <div key={i} className="bg-white border-2 border-[#1E293B] p-5 rounded-2xl flex justify-between items-center shadow-[3px_3px_0_0_#1E293B]">
                        <h4 className="text-lg">INCIDENT_LOG_00{i}</h4>
                        <span className="text-[10px] bg-emerald-500 text-white px-3 py-1 rounded-full">RESOLVED</span>
                    </div>
                  ))}
                </div>
              )}

              {/* Other filters would go here... */}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CitizensTab;
